import { Route, Routes, HashRouter as Router, Link } from "react-router-dom"
import React, { useState, useEffect, useCallback } from "react"
import axios from "axios"
import ApplyLeave from "./ApplyLeave"
import Home from "./Home"
import SwitchUser from "./SwitchUser"
import UserProfile from "./components/UserProfile"
import { trackPromise } from "react-promise-tracker"
import ApprovalCenter from "./ApprovalCenter"
import CancelLeave from "./CancelLeave"
import PartnersLeave from "./PartnersLeave"
import ShowAlert from "./components/ShowAlert"
import Requisition from "./Requisition"



const logout = () => {
  localStorage.clear()
  window.location = "/logout"
}

const gotoPowerBI = () => {    
  
  const url = "https://app.powerbi.com/groups/017b68cb-772c-4dac-83fc-eb7dfe15a888/reports/678098c9-99d6-44b0-8a9b-a5bcd4cc121e/ReportSection"
  const newWindow = window.open(url, "_blank", "noopener,noreferrer")
  if (newWindow) newWindow.opener = null
  
}

const gotoLeaveSummaryPowerBI = () => {    
  
  const url = "https://app.powerbi.com/links/8uT37X-B-j?ctid=42ab9b91-5029-47c6-8f78-38a33f843520&pbi_source=linkShare"
  const newWindow = window.open(url, "_blank", "noopener,noreferrer")
  if (newWindow) newWindow.opener = null
  
}


const App = () => {
  const [userProfile, setUserProfile] = useState({})    
  const [currentRacf, setCurrentRacf] = useState(null)
  const [superUser, setSuperUser] = useState(false)
  const [powerBI, setpowerBI] = useState(false) 
  const [allowRequisition, setAllowRequisition] = useState(false) 
  const [userOffice, setUserOffice] = useState("") 
  const [superUserMode, setSuperUserMode] = useState(false)  
  const [partnersMode, setPartnersMode] = useState(false)
  const [alert, setAlert] = useState({ position: 100 }) 

  // SharePoint
  const [sharePointPath, setSharePointPath] = useState("") 

  const login = () => {
    //localStorage.clear()
    window.location = "/login"
  }

    
  const setDisplayAlert = useCallback((alert_in) => {
      // alert comes in as { message: "hi", position: 0, timeout: 3000, color: "alert__green" }      
      setAlert(alert_in)
      setTimeout(function () {
        // Following is to remove alert message off from screen  
        setAlert({ position: 100 })
      }, alert_in.timeout)
   },[])
  
   const displayAndLogin = useCallback((msg) => {
    const _alert = {...msg, message:msg.message + " Now, taking you to the login page..."}
    setDisplayAlert(_alert);
    setTimeout(() => { 
      login();
    }, msg.timeout)
  }, [setDisplayAlert])

 
  useEffect(() => {
    trackPromise(
      axios({
        url: "/api/getUserProfile",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"
        },
        data: JSON.stringify({})   // seems like this line has to be removed to avoid error from Heroku as this line is passing empty parameter.
      })
        .then(response => response.data)
        .then(response => {
          setUserProfile(response["userProfile"])          
          setCurrentRacf(response["userProfile"]['racf'])
          setUserOffice(response["userProfile"]['office'])
          setSuperUser(response["userProfile"]['superUser'])
          setpowerBI(response["userProfile"]['powerBI'])       
          setAllowRequisition(response["userProfile"]['requisition'])       
          setSharePointPath(response["sharePointPath"])     
          setPartnersMode(response["userProfile"]['partnersMode'])
        })
        .catch(error => {
          console.log(error)
        })
    )
  }, [])


    // Convert to MM/DD/YY
  function convert2MMDDYY(iso_date) {
      let new_date =  iso_date.slice(0, 10).split('-')
      new_date = new_date[1] + "/" + new_date[2] + "/" + new_date[0][2] + new_date[0][3]
      return new_date
  } 
  
    // convert to local time
  function convertToLocal(date) {
      //const t = new Date(date).toTimeString()
      const d = new Date(date).toDateString()
      var local = d 
      //var local = d + " " + t
      //var local_end = local.search("GMT+") - 1
      //local = local.substring(0, local_end)
      //console.log('local time',local)
      return local
  }
  

    // convert to local time
  function convertToLocalTime(date) {
      const t = new Date(date).toTimeString()
      const d = new Date(date).toDateString()
      var local = d + " " + t
      var local_end = local.search("GMT+") - 1
      local = local.substring(0, local_end)
      //console.log('local time',local)
      return local
  }
   
  return (
    <div className="container">
      <div className="flex-row">
        <div className="flex-large">
          <UserProfile userProfile={userProfile} setSuperUserMode={setSuperUserMode} superUser={superUser} superUserMode={superUserMode} powerBI={powerBI}  partnersMode={partnersMode} setPartnersMode={setPartnersMode} />
          <Router>
            <nav>
              <ul className="app_header">                
                <li>
                  <Link to="/" className="link" > 
                    Home 
                  </Link>
                </li>      
                {userOffice !== 'NY' && (
                  <li>
                    <Link to="/ApplyLeave" className="link">
                      Apply Leave  
                    </Link>
                  </li>
                )}  

                {userOffice !== 'NY' && (
                <li>
                  <Link to="/CancelLeave" className="link" > 
                    Cancel
                  </Link>
                </li>
                )}  
          
                <li>
                  <Link to="/ApprovalCenter" className="link" > 
                    Approval Center
                  </Link>
                </li>      

                {allowRequisition ? (
                <li>
                 <Link to="/Requisition" className="link" > 
                  Requisition
                  </Link>
                </li> 
                ) : null}   

                {partnersMode ? (
                <li>
                  <Link to="/PartnersLeave" className="link">
                    Partners Status
                  </Link>
                </li>                                
                ) : null}   
                
                {superUser ? (
                <li>
                  <Link to="/SwitchUser" className="link" > 
                    Switch User  
                  </Link>
                </li>                                
                ) : null}

                {powerBI ? (
                  <li
                    className="link"
                    onClick={() => {
                      gotoPowerBI()
                    }}
                  >
                    Power BI
                  </li>
                ) : null}
              
              {userOffice !== 'NY' && (
                <li
                  className="link"
                  onClick={() => {
                    gotoLeaveSummaryPowerBI()
                  }}
                >
                  Leave Summary 
                </li>
              )}

                <button
                  className="fa fa-sign-out"
                  onClick={() => {
                    logout()
                  }}
                >
                  Logout
                </button>                
              </ul>
            </nav>
            {alert.position === 3 ? (
                <div className="flex-row">
                    <div className="flex-large">
                      <ShowAlert alert={alert} />
                    </div>
                </div>
            ) : null}
            <Routes>
              
              <Route path="/" element={<Home env={userProfile.environment}  currentRacf={currentRacf} />} />
              
              <Route path="/PartnersLeave" element={<PartnersLeave currentRacf={currentRacf}  setDisplayAlert={setDisplayAlert}     convertToLocal={convertToLocal} />} />
              
              <Route path="/ApplyLeave" element={<ApplyLeave currentRacf={currentRacf}  superUserMode={superUserMode} setDisplayAlert={setDisplayAlert} userProfile={userProfile}  
                  convert2MMDDYY={convert2MMDDYY}  sharePointPath={sharePointPath} convertToLocalTime={convertToLocalTime} alert={alert} />} />

              <Route path="/ApprovalCenter" element={<ApprovalCenter currentRacf={currentRacf} setDisplayAlert={setDisplayAlert} superUserMode={superUserMode}   convert2MMDDYY={convert2MMDDYY}
                convertToLocal={convertToLocal} sharePointPath={sharePointPath}
              />} />
              <Route path="/CancelLeave" element={<CancelLeave currentRacf={currentRacf}  setDisplayAlert={setDisplayAlert}  superUserMode={superUserMode}  convert2MMDDYY={convert2MMDDYY} 
                convertToLocal={convertToLocal}              
              />} />
              <Route path="/SwitchUser" element={<SwitchUser   currentRacf={currentRacf}  setCurrentRacf = {setCurrentRacf} displayAndLogin={displayAndLogin} setUserProfile={setUserProfile} />} />

              <Route path="/Requisition" element={<Requisition currentRacf={currentRacf}  setDisplayAlert={setDisplayAlert} userProfile={userProfile}  
                  convert2MMDDYY={convert2MMDDYY} superUserMode={superUserMode} convertToLocal={convertToLocal}  alert={alert} />} />


            </Routes>
          </Router>
        </div>
        
      </div>

    </div>
  )
}

export default App
