import React, { useState, Fragment, useEffect, useRef } from "react"
import ShowAlert from "./components/ShowAlert"
import SelectType from "./components/SelectType"
import EnterLeave from "./components/EnterLeave"

import { trackPromise } from "react-promise-tracker"
import ShowSpinner from "./components/ShowSpinner"

// import SharePoint from "./components/sharePoint/SharePoint"
// import ShowSharePointFiles from "./components/sharePoint/ShowSharePointFiles"
// import UploadForm from "./components/sharePoint/UploadForm"
import { v4 as uuidv4 } from "uuid"

function convertToLocal(date) {
  const t = new Date(date).toTimeString()
  const d = new Date(date).toDateString()
  var local = d + " " + t
  var local_end = local.search("GMT+") - 1
  local = local.substring(0, local_end)
  return local
}

const ApplyLeave = props => {
  const { currentRacf, superUserMode, setDisplayAlert, userProfile, staff, years, convert2MMDDYY, convertToLocalTime, alert} = props     
  const [year, setYear] = useState("")
  const [leaveType, setLeaveType] = useState("")  
  const [refreshPage, setRefreshPage] = useState(false)
  const [leaveList, setLeaveList] = useState([])
  const [refDetails, setRefDetails] = useState([])
 
  // const [sharePointID, setSharePointID] = useState("")    
  // const [refreshSharePointList, setRefreshSharePointList] = useState(false)
  // const [sharePointFiles, setSharePointFiles] = useState([])

  const [attachments, setAttachments] = useState([])
  const [attachmentID, setAttachmentID] = useState([])

  const fileInputRef = useRef(null)
  

  console.log (attachments)
  useEffect(() => {
    let root = document.querySelector(":root")
    const userAgent = navigator.userAgent.toLowerCase()
    const isTablet = /(ipad|tablet|(android(?!.*mobile))|(windows(?!.*phone)(.*touch))|kindle|playbook|silk|(puffin(?!.*(IP|AP|WP))))/.test(userAgent)

    if (isTablet) {
      root.style.setProperty("--changeTrack_scroll_width", "7fr")
    } else {
      root.style.setProperty("--changeTrack_scroll_width", "6.7fr")
    }

    if (userAgent.includes("safari") && userAgent.includes("macintosh")) {
      root.style.setProperty("--changeTrack_scroll_width", "7fr")
    }
    
  }, [])

  useEffect(() => {    
    setAttachmentID(uuidv4())
  }, [refreshPage])

  
  const handleAttachment = event => {
    const selectedFiles = Array.from(event.target.files)
    
    let hasDuplicate = false
    const uniqueNewFiles = []
    const existingNames = new Set(attachments.map(file => file.name))

    selectedFiles.forEach(file => {
      if (existingNames.has(file.name)) {
        hasDuplicate = true
      } else {
        existingNames.add(file.name)
        uniqueNewFiles.push(file)
      }
    })

    if (hasDuplicate) {
      setDisplayAlert({ message: "Duplicate file names are not allowed.", position: 4, timeout: 4000, color: "alert__red" })
    }

    if (uniqueNewFiles.length > 0) {
      setAttachments(prev => [...prev, ...uniqueNewFiles])
    }

    if (fileInputRef.current) {
      fileInputRef.current.value = ""
    }
  }

  const removeFile = indexToRemove => {
    setAttachments(prev => prev.filter((_, index) => index !== indexToRemove))
  }

  const clearAttachments = () => {
    setAttachments([])
    if (fileInputRef.current) {
      fileInputRef.current.value = ""
    }
  }

  const printSummary = async (file_name) => {
      try {
        file_name = "Leave Summary for " + year + " (" + currentRacf + ").xlsx"
                    
        const response = await trackPromise(
          fetch("/eleave/api/printsummary", {
            method: "POST",
            headers: {
              "Content-Type": "application/octet-stream",
              "Content-Disposition": "attachment",
              "Cache-Control": "no-cache",
              "localTime": JSON.stringify(convertToLocal(Date.now())),
              "parameters": JSON.stringify({ year: Number(year), racf: currentRacf })          
            }

        }), "printSummary")    

        if (!response.ok) {
          const data = await response.text();   
          const msg = JSON.parse(data).error_message          
          setDisplayAlert({ message: msg, position: 3, timeout: 4000, color: "alert__red" } )          
        }
        else {
          const data = await response.blob();          
          const url = window.URL.createObjectURL(data)
          const link = document.createElement("a")
          link.href = url  
          link.setAttribute("download", file_name)
          document.body.appendChild(link)
          link.click()
          link.parentNode.removeChild(link)          
        }
        return null

    }
    catch {}               
      setDisplayAlert({ message: "The summary seems no data !  Please check !", position: 3, timeout: 4000, color: "alert__red" })                
    }

  const handlePrintSummary = event => {
    const id = event.target.id

    if (id === "printSummary") {
      printSummary("Leave Summary.xlsx")
    }
  }

  return (
    <Fragment>
      <div className="subHeading"> Apply Leave</div>
      
      <button id="printSummary" onClick={handlePrintSummary}>
        Print Leave Summary
      </button>

      <SelectType userProfile={userProfile} staff={staff} years={years} year={year} setYear={setYear} leaveType={leaveType} setLeaveType={setLeaveType} setDisplayAlert={setDisplayAlert} currentRacf={currentRacf}
             refreshPage={refreshPage}  convert2MMDDYY={convert2MMDDYY} setLeaveList={setLeaveList} superUserMode={superUserMode}  convertToLocal={convertToLocal} refDetails={refDetails} setRefDetails={setRefDetails}
      />

      {alert.position === 1 ? (
        <div className="flex-row">
          <div className="flex-large">
            <ShowAlert alert={alert} />
          </div>
        </div>
      ) : null}

      {alert.position === 4 ? (
        <div className="flex-row">
          <div className="flex-large">
            <ShowAlert alert={alert} />
          </div>
        </div>
      ) : null}
      
      <ShowSpinner position={4} />

      {leaveType && leaveType === "LVE04" ? (
        <Fragment>
          <div className="separator">Document Upload</div>
          <div className="upload_grid">
            <div className="upload_grid_content">
              <div className="attachment-label">Medical Certificate:</div>
              <div className="attachment-wrapper">
                <div className="file-actions-col">
                  <label className="custom-file-upload">
                    <input 
                      type="file" 
                      className="hidden-file-input"
                      onChange={handleAttachment}
                      ref={fileInputRef}
                      multiple
                    />
                    Choose Files
                  </label>
                  <button 
                    type="button" 
                    className="clear-files-btn" 
                    onClick={clearAttachments}
                    disabled={attachments.length === 0}
                  >
                    Clear Files
                  </button>
                </div>
                
                <div className="file-list-area">
                  {attachments.map((file, index) => (
                    <div key={index} className="file-list-item">
                      <span className="file-name" title={file.name}>{file.name}</span>
                      <button 
                        type="button" 
                        className="remove-file-btn" 
                        onClick={() => removeFile(index)}
                      >
                        ×
                      </button>
                    </div>
                  ))}
                  {Array.from({ length: Math.max(0, 3 - attachments.length) }).map((_, index) => (
                    <div key={`empty-${index}`} className="file-list-item empty-slot"></div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </Fragment>
      ) : null}

      <ShowSpinner position={3} />
      <EnterLeave year={year} racf={currentRacf} office={userProfile.office} superUserMode={superUserMode} leaveType={leaveType} setDisplayAlert={setDisplayAlert} setRefreshPage={setRefreshPage} 
      leaveList={leaveList} setLeaveList={setLeaveList} refDetails={refDetails} convertToLocalTime={convertToLocalTime} attachments={attachments} attachmentID={attachmentID} />

    </Fragment>
  )
}
export default ApplyLeave